"""
Resolve Source Template ID — find organization config template by name or ID.

Workflow inputs (script_arguments):
  argv[1]  config templates JSON (Get Organization Config Templates output)
  argv[2]  Source Template input (exact name or numeric template ID)

Script queries:
  template_id  (string; empty when not found)
"""

import sys
import json

template_id = ""


def parse_templates(raw):
    try:
        data = json.loads(raw) if raw else []
    except Exception:
        return []
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("templates", "configTemplates", "items", "data", "results"):
            val = data.get(key)
            if isinstance(val, list):
                return val
    return []


def main():
    global template_id
    templates = parse_templates(sys.argv[1] if len(sys.argv) > 1 else "[]")
    needle = (sys.argv[2] if len(sys.argv) > 2 else "").strip()
    if not needle:
        return
    for entry in templates:
        if not isinstance(entry, dict):
            continue
        tid = entry.get("id")
        name = entry.get("name")
        if name is not None and str(name) == needle:
            template_id = "" if tid is None else str(tid)
            return
        if tid is not None and str(tid) == needle:
            template_id = str(tid)
            return


try:
    main()
except Exception:
    template_id = ""

"""
Calculate Payload — Meraki Alert Sync workflow script.

Workflow inputs (script_arguments):
  argv[1]  source alerts JSON
  argv[2]  destination alerts JSON
  argv[3]  destination webhooks JSON
  argv[4]  mode: "merge" or "replace"
  argv[5]  destination network name

Script queries to register:
  alert_payload
  default_destination_payload
  muting_payload
  result_entry  (object)

result_entry.outcome values set by this script:
  invalid        — validation failed for this network
  no_change      — valid, destination already matches
  pending_apply  — valid, changes required (apply step sets applied/dry_run/apply_failed)

Alert types present on destination but missing on source are kept as-is on the
destination. They are recorded in result_entry.source_gaps and reported in the
description — they do not fail execution.
"""

import sys
import json
import copy

CONVERT_EMPTY_ARRAYS_TO_NULL = True

VALID_MODES = ("merge", "replace")


def get_json(arg, default):
    try:
        return json.loads(arg) if arg else default
    except Exception:
        return default


def empty_dest():
    return {
        "emails": [],
        "smsNumbers": [],
        "httpServerIds": [],
        "allAdmins": False,
        "snmp": False,
    }


def dedupe(values):
    return sorted(set(str(v) for v in values)) if values else []


def norm_dest(d, valid_ids):
    d = d or {}
    return {
        "emails": dedupe(d.get("emails")),
        "smsNumbers": dedupe(d.get("smsNumbers")),
        "allAdmins": bool(d.get("allAdmins")),
        "snmp": bool(d.get("snmp")),
        "httpServerIds": dedupe(
            s for s in (d.get("httpServerIds") or []) if str(s) in valid_ids
        ),
    }


def merge_dest(a, b, valid_ids):
    a, b = norm_dest(a, valid_ids), norm_dest(b, valid_ids)
    return {
        "emails": dedupe(a["emails"] + b["emails"]),
        "smsNumbers": dedupe(a["smsNumbers"] + b["smsNumbers"]),
        "httpServerIds": dedupe(a["httpServerIds"] + b["httpServerIds"]),
        "allAdmins": a["allAdmins"] or b["allAdmins"],
        "snmp": a["snmp"] or b["snmp"],
    }


def cleanup_alerts(defaults, alerts, valid_ids):
    def_emails = {e.strip().lower() for e in (defaults.get("emails") or [])}
    def_hooks = {str(x) for x in (defaults.get("httpServerIds") or [])}
    out = []
    for alert in alerts:
        a = alert.copy()
        dest = norm_dest(a.get("alertDestinations"), valid_ids)
        dest["emails"] = [e for e in dest["emails"] if e.strip().lower() not in def_emails]
        dest["httpServerIds"] = [x for x in dest["httpServerIds"] if str(x) not in def_hooks]
        a["alertDestinations"] = dest
        out.append(a)
    return out


def fix_selector(alert):
    f = alert.get("filters")
    if not f or "selector" not in f:
        return alert
    v = f["selector"]
    if isinstance(v, (dict, list)):
        f["selector"] = json.dumps(v, separators=(",", ":"))
    elif isinstance(v, str):
        try:
            p = json.loads(v)
            if isinstance(p, str):
                f["selector"] = p
        except ValueError:
            pass
    return alert


def to_null(obj):
    if not CONVERT_EMPTY_ARRAYS_TO_NULL:
        return obj
    if isinstance(obj, dict):
        return {k: to_null(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return None if not obj else [to_null(x) for x in obj]
    return obj


def by_type(alerts):
    return {a["type"]: a for a in alerts if a.get("type")}


def norm_alert(alert, valid_ids):
    a = alert.copy()
    a["alertDestinations"] = norm_dest(a.get("alertDestinations"), valid_ids)
    return fix_selector(a)


def baseline_dest_alerts(alerts, defaults, valid_ids):
    defs = norm_dest(defaults, valid_ids)
    cleaned = cleanup_alerts(
        defs, [norm_alert(a, valid_ids) for a in alerts], valid_ids
    )
    return defs, by_type(cleaned)


def list_default_changes(before, after):
    labels = []
    if before.get("emails") != after.get("emails"):
        labels.append("emails")
    if before.get("smsNumbers") != after.get("smsNumbers"):
        labels.append("sms")
    if before.get("httpServerIds") != after.get("httpServerIds"):
        labels.append("webhooks")
    if before.get("allAdmins") != after.get("allAdmins"):
        labels.append("allAdmins")
    if before.get("snmp") != after.get("snmp"):
        labels.append("snmp")
    return labels


def list_muting_changes(before, after):
    keys = set(before or {}) | set(after or {})
    return sorted(k for k in keys if (before or {}).get(k) != (after or {}).get(k))


def build_description(mode, alert_count, default_changes, muting_changes, missing_types=None):
    parts = []
    if alert_count:
        parts.append(str(alert_count) + " alert(s)")
    if default_changes:
        parts.append("defaults: " + ", ".join(default_changes))
    if muting_changes:
        parts.append("muting: " + ", ".join(muting_changes))
    if missing_types:
        parts.append(
            "source gaps (kept dest): " + ", ".join(missing_types)
        )
    if parts:
        return mode + " — " + "; ".join(parts)
    return "No changes required"


def make_entry(
    net,
    mode,
    status,
    outcome,
    desc,
    req,
    alerts="0",
    defs="none",
    muting="none",
    source_gaps="none",
):
    return {
        "network": net,
        "mode": mode,
        "status": status,
        "outcome": outcome,
        "description": desc,
        "require_update": req,
        "changed_alert_count": alerts,
        "defaults_changed": defs,
        "muting_changed": muting,
        "source_gaps": source_gaps,
    }


def missing_source_types(dest_alerts, source_alerts):
    dest_types = {a.get("type") for a in dest_alerts if a.get("type")}
    source_types = {a.get("type") for a in source_alerts if a.get("type")}
    return sorted(dest_types - source_types)


def collect_used_webhook_ids(source_dest, source_alerts):
    used = set()
    for sid in source_dest.get("httpServerIds") or []:
        used.add(str(sid))
    for alert in source_alerts:
        for sid in (alert.get("alertDestinations") or {}).get("httpServerIds") or []:
            used.add(str(sid))
    return used


def build_merge_payload(d_alerts, d_dest, d_muting, source_map, s_dest, s_muting, hook_ids):
    final_dest = merge_dest(d_dest, s_dest, hook_ids)
    final_muting = dict(d_muting)
    final_muting.update(s_muting)
    final_alerts = []
    for da in d_alerts:
        na = da.copy()
        sa = source_map.get(na.get("type"))
        if sa:
            na["enabled"] = bool(na.get("enabled") or sa.get("enabled"))
            na["alertDestinations"] = merge_dest(
                na.get("alertDestinations"), sa.get("alertDestinations"), hook_ids
            )
            if sa.get("filters"):
                na["filters"] = copy.deepcopy(sa["filters"])
            na = fix_selector(na)
        final_alerts.append(na)
    return final_dest, final_muting, final_alerts


def build_replace_payload(d_alerts, source_map, s_dest, s_muting, hook_ids):
    final_dest = norm_dest(s_dest, hook_ids)
    final_muting = copy.deepcopy(s_muting)
    final_alerts = []
    for da in d_alerts:
        alert_type = da.get("type")
        sa = source_map.get(alert_type)
        if not sa:
            na = da.copy()
        else:
            na = sa.copy()
            na["alertDestinations"] = norm_dest(sa.get("alertDestinations"), hook_ids)
            if sa.get("filters"):
                na["filters"] = copy.deepcopy(sa["filters"])
            elif "filters" in na:
                del na["filters"]
            na = fix_selector(na)
        final_alerts.append(na)
    return final_dest, final_muting, final_alerts


# --- inputs ---
source = get_json(sys.argv[1], {})
dest = get_json(sys.argv[2], {})
webhooks = get_json(sys.argv[3], [])
mode = (sys.argv[4] if len(sys.argv) > 4 else "merge").strip().lower()
net_name = sys.argv[5] if len(sys.argv) > 5 else ""

s_alerts = source.get("alerts") or []
s_dest = source.get("defaultDestinations") or {}
s_muting = source.get("muting") or {}
d_alerts = dest.get("alerts") or []
d_dest = dest.get("defaultDestinations") or {}
d_muting = dest.get("muting") or {}

# --- outputs ---
alert_payload = "[]"
default_destination_payload = "{}"
muting_payload = "{}"
status = "invalid"
outcome = "invalid"
description = "Not evaluated"
require_update = "true"
result_entry = make_entry(net_name, mode, status, outcome, description, require_update)

hook_ids = {str(w["id"]) for w in webhooks if w.get("id")}

try:
    missing_types = missing_source_types(d_alerts, s_alerts)
    source_gaps = ", ".join(missing_types) if missing_types else "none"

    if mode not in VALID_MODES:
        description = "Invalid mode '" + mode + "'. Use merge or replace"
        result_entry = make_entry(net_name, mode, status, outcome, description, require_update)

    else:
        used_hooks = collect_used_webhook_ids(s_dest, s_alerts)
        missing_hooks = sorted(x for x in used_hooks if x not in hook_ids)

        if missing_hooks:
            description = "Missing webhook IDs on destination: " + ", ".join(missing_hooks)
            result_entry = make_entry(net_name, mode, status, outcome, description, require_update)

        else:
            before_alerts = copy.deepcopy(d_alerts)
            before_dest = copy.deepcopy(d_dest)
            before_muting = copy.deepcopy(d_muting)
            source_map = by_type(s_alerts)

            if mode == "merge":
                final_dest, final_muting, final_alerts = build_merge_payload(
                    d_alerts, d_dest, d_muting, source_map, s_dest, s_muting, hook_ids
                )
            else:
                final_dest, final_muting, final_alerts = build_replace_payload(
                    d_alerts, source_map, s_dest, s_muting, hook_ids
                )

            final_alerts = cleanup_alerts(final_dest, final_alerts, hook_ids)

            before_dest_cmp, before_map = baseline_dest_alerts(
                before_alerts, before_dest, hook_ids
            )
            changed = [
                a for a in final_alerts if a != before_map.get(a.get("type"), {})
            ]
            default_changes = list_default_changes(before_dest_cmp, final_dest)
            muting_changes = list_muting_changes(before_muting, final_muting)
            has_changes = bool(changed) or bool(default_changes) or bool(muting_changes)

            put = {}
            if default_changes:
                put["defaultDestinations"] = final_dest
            if changed:
                put["alerts"] = changed
            if muting_changes:
                put["muting"] = final_muting

            status = "valid"
            description = build_description(
                mode, len(changed), default_changes, muting_changes, missing_types
            )
            require_update = "false" if not has_changes else "true"
            outcome = "no_change" if not has_changes else "pending_apply"

            alert_payload = json.dumps(to_null(changed))
            default_destination_payload = json.dumps(
                to_null(final_dest if default_changes else {})
            )
            muting_payload = json.dumps(to_null(final_muting if muting_changes else {}))

            result_entry = make_entry(
                net_name,
                mode,
                status,
                outcome,
                description,
                require_update,
                str(len(changed)),
                ", ".join(default_changes) if default_changes else "none",
                ", ".join(muting_changes) if muting_changes else "none",
                source_gaps,
            )

except Exception as e:
    status = "invalid"
    outcome = "invalid"
    description = "Script error: " + str(e)
    require_update = "true"
    alert_payload = json.dumps(d_alerts)
    default_destination_payload = json.dumps(d_dest)
    muting_payload = json.dumps(d_muting)
    result_entry = make_entry(net_name, mode, status, outcome, description, require_update)

"""
Accumulate Results — Meraki Alert Sync workflow script.

Workflow inputs (script_arguments):
  argv[1]  results so far (Local - Results List)
  argv[2]  result_entry from Calculate Payload (object)
  argv[3]  apply step outcome (Local - Last Update Result)

Script queries to register:
  updated_list  (string JSON array)

Apply step values (set by condition blocks after Calculate Payload):
  invalid            — validation failed (pass-through from calculate)
  no_change          — no changes required
  dry_run            — dry-run, changes not applied
  <API JSON/text>    — Update Alerts atomic output (success or failure)
"""

import sys
import json

SUCCESS_CODES = frozenset({"200", "204"})


def parse_json_list(raw):
    try:
        data = json.loads(raw) if raw else []
        return data if isinstance(data, list) else []
    except Exception:
        return []


def parse_entry(raw):
    try:
        data = json.loads(raw) if raw else {}
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def api_response_indicates_failure(response):
    if not isinstance(response, dict):
        return False

    for key in ("status", "statusCode", "code", "httpStatus"):
        if key not in response:
            continue
        value = str(response[key])
        if value not in SUCCESS_CODES:
            return True

    for key in ("error", "errors", "message"):
        if response.get(key):
            return True

    return False


def resolve_outcome(entry, apply_step):
    outcome = entry.get("outcome", "invalid")
    description = str(entry.get("description", "")).strip()
    status = entry.get("status", "invalid")

    if outcome in ("invalid", "no_change"):
        return status, outcome, description

    if outcome != "pending_apply":
        return status, outcome or "invalid", description

    step = (apply_step or "").strip()
    step_lower = step.lower()

    if step_lower == "invalid":
        return "invalid", "invalid", description

    if step_lower == "no_change":
        return "valid", "no_change", description

    if step_lower == "dry_run":
        return "valid", "dry_run", description

    if not step:
        return "invalid", "apply_failed", description + " | Apply step did not run"

    try:
        response = json.loads(step)
        if api_response_indicates_failure(response):
            return "invalid", "apply_failed", description + " | API failed: " + step
        return "valid", "applied", description
    except (ValueError, TypeError):
        pass

    if any(token in step_lower for token in ("fail", "error", "exception")):
        return "invalid", "apply_failed", description + " | API failed: " + step

    return "valid", "applied", description


# --- inputs ---
results = parse_json_list(sys.argv[1] if len(sys.argv) > 1 else "[]")
entry = parse_entry(sys.argv[2] if len(sys.argv) > 2 else "{}")
apply_step = sys.argv[3] if len(sys.argv) > 3 else ""

status, outcome, description = resolve_outcome(entry, apply_step)

entry["status"] = status
entry["outcome"] = outcome
entry["description"] = description

results.append(entry)
result_json = json.dumps(results)

"""
Format Final Report — Meraki Alert Sync workflow script.

Workflow inputs (script_arguments):
  argv[1]  results list JSON (Local - Results List)
  argv[2]  Dry-Run input: "true" / "false"
  argv[3]  sync mode: "merge" or "replace" (Mode)

Script queries to register:
  report           — human-readable text report
  overallStatus    — Success | Partial | Failed
  statusCode       — 200 | 207 | 500
  errorMessage     — detail when not fully successful; empty on Success
  resultJson       — structured JSON for downstream workflows

Expected result_entry.outcome values:
  invalid        — validation failed for this network
  no_change      — destination already matched source
  pending_apply  — should not appear in final report (apply step not run)
  applied        — API update succeeded
  dry_run        — dry-run, changes were not applied
  apply_failed   — API update failed
"""

import sys
import json

OUTCOME_LABELS = {
    "invalid": "FAIL",
    "no_change": "SKIP",
    "pending_apply": "PENDING",
    "applied": "OK",
    "dry_run": "DRY-RUN",
    "apply_failed": "FAIL",
}

OUTCOME_ORDER = {
    "applied": 0,
    "dry_run": 1,
    "no_change": 2,
    "invalid": 3,
    "apply_failed": 4,
    "pending_apply": 5,
}


def parse_bool(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    text = str(value).strip().lower()
    if text in ("true", "1", "yes", "on"):
        return True
    if text in ("false", "0", "no", "off", ""):
        return False
    try:
        parsed = json.loads(text)
        if isinstance(parsed, bool):
            return parsed
    except Exception:
        pass
    return False


def resolve_dry_run(argv, counts):
    if len(argv) > 2 and str(argv[2]).strip():
        return parse_bool(argv[2])
    return counts["dry_run"] > 0


def parse_results(raw):
    try:
        data = json.loads(raw) if raw else []
        return data if isinstance(data, list) else []
    except Exception:
        return []


def count_source_gaps(results):
    return sum(
        1
        for entry in results
        if entry.get("source_gaps") and entry.get("source_gaps") != "none"
    )


def count_by_outcome(results):
    counts = {
        "applied": 0,
        "dry_run": 0,
        "no_change": 0,
        "invalid": 0,
        "apply_failed": 0,
        "pending_apply": 0,
    }
    for entry in results:
        outcome = entry.get("outcome", "invalid")
        if outcome not in counts:
            outcome = "invalid"
        counts[outcome] += 1
    return counts


def derive_overall_status(counts, total):
    if total == 0:
        return "Failed"
    failures = counts["invalid"] + counts["apply_failed"]
    successes = counts["applied"] + counts["dry_run"] + counts["no_change"]
    if failures == 0:
        return "Success"
    if successes > 0:
        return "Partial"
    return "Failed"


def derive_status_code(overall_status):
    if overall_status == "Success":
        return "200"
    if overall_status == "Partial":
        return "207"
    return "500"


def derive_error_message(overall_status, counts, total, script_error=""):
    if script_error:
        return script_error

    failures = counts["invalid"] + counts["apply_failed"]

    if overall_status == "Success":
        return ""

    if total == 0:
        return "No destination networks found in the organization."

    if overall_status == "Partial":
        return (
            str(failures)
            + " of "
            + str(total)
            + " network(s) failed. See Result for per-network details."
        )

    if counts["pending_apply"]:
        return (
            str(counts["pending_apply"])
            + " network(s) had unexpected pending apply state. See Result for details."
        )

    return (
        str(failures)
        + " of "
        + str(total)
        + " network(s) failed. See Result for per-network details."
    )


def build_result_json(results, sync_mode, dry_run, counts, gap_count, overall_status):
    payload = {
        "summary": {
            "overallStatus": overall_status,
            "syncMode": sync_mode,
            "dryRun": dry_run,
            "totalNetworks": len(results),
            "counts": {
                "applied": counts["applied"],
                "dryRun": counts["dry_run"],
                "noChange": counts["no_change"],
                "invalid": counts["invalid"],
                "applyFailed": counts["apply_failed"],
                "pendingApply": counts["pending_apply"],
            },
            "sourceGapNetworks": gap_count,
        },
        "networks": sort_results(results),
    }
    return json.dumps(payload, separators=(",", ":"))


def format_network_line(entry):
    outcome = entry.get("outcome", "invalid")
    label = OUTCOME_LABELS.get(outcome, "FAIL")
    network = str(entry.get("network", "unknown"))
    description = str(entry.get("description", "")).strip()
    if description:
        return "[" + label + "] " + network + " — " + description
    return "[" + label + "] " + network


def sort_results(results):
    return sorted(
        results,
        key=lambda r: (
            OUTCOME_ORDER.get(r.get("outcome", "invalid"), 99),
            str(r.get("network", "")).lower(),
        ),
    )


def build_report(results, sync_mode, dry_run, counts, gap_count):
    total = len(results)
    lines = [
        "Alert Sync Report",
        "=" * 50,
        "Sync mode: " + sync_mode,
        "Dry-Run: " + ("YES — no changes were applied" if dry_run else "NO"),
        "",
        "Summary",
        "  Total networks:  " + str(total),
        "  Applied:           " + str(counts["applied"]),
        "  Dry-Run:           " + str(counts["dry_run"]),
        "  No change:         " + str(counts["no_change"]),
        "  Failed:            " + str(counts["invalid"] + counts["apply_failed"]),
        "  Source gaps:       " + str(gap_count),
    ]

    if counts["pending_apply"]:
        lines.append("  Pending (unexpected): " + str(counts["pending_apply"]))

    notes = []
    if emulation and counts["dry_run"]:
        notes.append("Dry-Run entries show what would have been applied.")
    if gap_count:
        notes.append(
            "Source gaps: alert types on destination but not on source were left unchanged."
        )
    if notes:
        lines.extend(["", "Notes", *[("  - " + note) for note in notes]])

    lines.extend(["", "Details", "-" * 50])

    if not results:
        lines.append("No destination networks found in the organization.")
    else:
        for entry in sort_results(results):
            lines.append(format_network_line(entry))

    return "\n".join(lines)


# --- defaults for workflow script queries ---
report = "Error generating report."
overall_status = "Failed"
status_code = "500"
error_message = "Error generating report."
result_json = "{}"

try:
    results = parse_results(sys.argv[1] if len(sys.argv) > 1 else "[]")
    sync_mode = (sys.argv[3] if len(sys.argv) > 3 else "merge").strip().lower()

    counts = count_by_outcome(results)
    emulation = resolve_emulation_mode(sys.argv, counts)
    gap_count = count_source_gaps(results)
    overall_status = derive_overall_status(counts, len(results))
    status_code = derive_status_code(overall_status)
    error_message = derive_error_message(overall_status, counts, len(results))
    report = build_report(results, sync_mode, dry_run, counts, gap_count)
    result_json = build_result_json(
        results, sync_mode, dry_run, counts, gap_count, overall_status
    )

except Exception as e:
    script_error = "Error generating report: " + str(e)
    report = script_error
    overall_status = "Failed"
    status_code = "500"
    error_message = script_error
    result_json = json.dumps(
        {
            "summary": {
                "overallStatus": "Failed",
                "syncMode": (sys.argv[3] if len(sys.argv) > 3 else "merge").strip().lower(),
                "dryRun": False,
                "totalNetworks": 0,
                "counts": {},
                "sourceGapNetworks": 0,
            },
            "networks": [],
